<?php declare(strict_types=1); ?>
<header class="page-header"><div><h1>Dienste & Übungen</h1><p>Termine planen, Rückmeldungen verfolgen und Anwesenheit vorbereiten.</p></div><button class="button button-primary" type="button" data-dialog-open="event-dialog"><svg><use href="#i-plus"/></svg>Dienst anlegen</button></header>
<section class="panel"><header class="panel-header"><h2>Alle Dienste</h2><span><?= count($events) ?> Termine</span></header><div class="table-wrap"><table><thead><tr><th>Datum</th><th>Titel</th><th>Art</th><th>Zeit</th><th>Ort</th><th>Status</th></tr></thead><tbody><?php if($events===[]):?><tr><td colspan="6" class="empty-cell">Noch keine Dienste angelegt.</td></tr><?php endif;?><?php foreach($events as $event):?><tr><td><?= e(german_date(substr($event['starts_at'],0,10))) ?></td><td><strong><?= e($event['title']) ?></strong></td><td><?= e(['practice'=>'Übung','meeting'=>'Besprechung','trip'=>'Ausflug','competition'=>'Wettbewerb','other'=>'Sonstiges'][$event['event_type']]??'Sonstiges') ?></td><td><?= e(substr($event['starts_at'],11,5)) ?>–<?= e(substr($event['ends_at'],11,5)) ?></td><td><?= e($event['location_name']?:'–') ?></td><td><span class="status status-success">Veröffentlicht</span></td></tr><?php endforeach;?></tbody></table></div></section>
<dialog class="modal" id="event-dialog"><form method="post" action="/events" class="modal-card"><?= csrf_field() ?><header><div><h2>Dienst anlegen</h2><p>Plane eine Übung, Besprechung oder Veranstaltung.</p></div><button type="button" class="icon-button" data-dialog-close aria-label="Schließen"><svg><use href="#i-close"/></svg></button></header><div class="form-grid"><label class="span-2">Titel<input name="title" required></label><label>Art<select name="event_type"><option value="practice">Übung</option><option value="meeting">Besprechung</option><option value="trip">Ausflug</option><option value="competition">Wettbewerb</option></select></label><label>Ort<input name="location_name"></label><label>Beginn<input type="datetime-local" name="starts_at" required></label><label>Ende<input type="datetime-local" name="ends_at" required></label><label class="span-2">Beschreibung<textarea name="description_text" rows="4"></textarea></label></div><footer><button type="button" class="button button-secondary" data-dialog-close>Abbrechen</button><button class="button button-primary">Dienst speichern</button></footer></form></dialog>
